import { afterAll, describe, expect, it } from "vitest";
import { createFixtureOrg } from "../helpers/fixtures";
import { closePool, sql } from "../helpers/db";
import { anonClient, userClient } from "../helpers/clients";
import { api } from "../helpers/http";
import { signIn } from "../helpers/seeded";
import { env } from "../helpers/env";

afterAll(closePool);

describe("helpers smoke", () => {
  it("fixture org, RLS via userClient, http with bearer, cached sign-in", async () => {
    const fx = await createFixtureOrg({
      lease: { startDate: "2026-01-31", endDate: "2026-07-15", monthlyRentSen: 150000, depositSen: 300000 },
    });
    expect(fx.lease!.invoices).toHaveLength(7);
    const rows = await sql<{ amount_sen: number; due_date: string }>(
      "select amount_sen, due_date from public.invoices where lease_id = $1 order by due_date, kind = 'rent', period_index",
      [fx.lease!.id],
    );
    expect(rows.at(-1)).toEqual({ amount_sen: 77419, due_date: "2026-06-30" });

    const { data: tA, error } = await userClient(fx.tokens.tenantA).from("tenants").select("id");
    expect(error).toBeNull();
    expect(tA).toEqual([{ id: fx.tenantAId }]);
    const { data: inv } = await userClient(fx.tokens.tenantB).from("invoices").select("id");
    expect(inv).toEqual([]);
    const { data: staffInv } = await userClient(fx.tokens.staff).from("invoices").select("id");
    expect(staffInv).toHaveLength(7);
    const anon = await anonClient().from("invoices").select("id");
    expect(anon.data ?? []).toEqual([]);

    const again = await signIn(fx.users.staff.email, env.seedPassword);
    expect(again.accessToken).toBe(fx.users.staff.accessToken);

    const r = await api(fx.tokens.manager).get(`/api/leases/${fx.lease!.id}`);
    console.log("GET lease status", r.status, env.baseUrl);
    const r2 = await api().get(`/api/leases/${fx.lease!.id}`);
    console.log("anon GET lease status", r2.status);
  });
});

